scriptedVariables.script:
const root = scope?.payload && typeof scope.payload === 'object' ? scope.payload : scope;
const items = root?.changelog?.items || root?.payload?.changelog?.items || [];
const statusItem = Array.isArray(items) ? items.find((item) => String(item.field || '').toLowerCase() === 'status') : null;
const toStatus = statusItem?.toString || statusItem?.to || root?.issue?.fields?.status?.name || '';
return toStatus === 'Send for Signature' ? 'true' : 'false';

